using System;\nusing NUnit.Framework;\nusing RestSharp;\nusing TechTalk.SpecFlow;\nusing AutomationFramework.API.BusinessLogic;\nusing Serilog;\nusing Newtonsoft.Json;\n\nnamespace AutomationFramework.API.StepDefinitions\n{\n    [Binding]\n    public class PetstoreSteps\n    {\n        private readonly ScenarioContext _scenarioContext;\n        private readonly PetApiHelper _petApiHelper;\n        private RestResponse _response;\n\n        public PetstoreSteps(ScenarioContext scenarioContext)\n        {\n            _scenarioContext = scenarioContext;\n            _petApiHelper = new PetApiHelper();\n        }\n\n        [Given(\"the API endpoint is \\\"(.*)\\\"\")]\n        public void GivenTheApiEndpointIs(string endpoint)\n        {\n            _scenarioContext[\"Endpoint\"] = endpoint;\n            Log.Information(\"Endpoint set to: {Endpoint}\", endpoint);\n        }\n\n        [Given(\"the request payload is\")]\n        public void GivenTheRequestPayloadIs(string payload)\n        {\n            _scenarioContext[\"Payload\"] = payload;\n            Log.Information(\"Payload set to: {Payload}\", payload);\n        }\n\n        [When(\"I send a POST request\")]\n        public void WhenISendAPostRequest()\n        {\n            var endpoint = _scenarioContext[\"Endpoint\"].ToString();\n            var payload = _scenarioContext[\"Payload\"].ToString();\n            _response = _petApiHelper.SendPostRequest(endpoint, payload);\n            Log.Information(\"POST request sent to {Endpoint} with payload: {Payload}\", endpoint, payload);\n        }\n\n        [When(\"I send a GET request\")]\n        public void WhenISendAGetRequest()\n        {\n            var endpoint = _scenarioContext[\"Endpoint\"].ToString();\n            _response = _petApiHelper.SendGetRequest(endpoint);\n            Log.Information(\"GET request sent to {Endpoint}\", endpoint);\n        }\n\n        [When(\"I send a PUT request\")]\n        public void WhenISendAPutRequest()\n        {\n